package com.interview.fraud.platform;
import java.time.Instant; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class IdempotentDomainEventConsumer {private final JdbcTemplate jdbc;private final AuditService audit;public IdempotentDomainEventConsumer(JdbcTemplate j,AuditService a){jdbc=j;audit=a;}@Transactional @KafkaListener(topics="fraud-domain-events",groupId="fraud-audit-consumer")public void consume(String payload,@org.springframework.messaging.handler.annotation.Header(org.springframework.kafka.support.KafkaHeaders.RECEIVED_KEY)String key){String id="consumer:audit:"+key;if(Boolean.TRUE.equals(jdbc.query("SELECT COUNT(*) FROM idempotency_keys WHERE idempotency_key=?",rs->{rs.next();return rs.getLong(1)>0;},id)))return;jdbc.update("INSERT INTO idempotency_keys(idempotency_key,response_ref,created_at) VALUES(?,?,?)",id,key,Instant.now());audit.log("kafka-consumer","DOMAIN_EVENT_CONSUMED","EVENT",key,payload);}}
